<script setup lang="ts">
import {usePayrollReturn} from '../payrollReturn'
const payrollReturn=usePayrollReturn()
import {computed,onMounted,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {usePayrollPage} from '../payrollPage'
import {blankRule,chooseCompany,copy,validRule} from '../payrollUi'
import {usePayrollConfigurationText} from '../payrollConfigurationText'
import {profileEmployee} from '../payrollConfigurationTypes'
import type {ProfilePreview} from '../payrollConfigurationTypes'
import {storeToday} from '../time'
import type {PayrollHomeData,PayProfilePage,SalaryTemplate,PayBasis,CpfProfile,PrDocument,PaymentPreference} from '../payrollTypes'
import type {Option} from '../types'
import CdacProfileFields from '../components/CdacProfileFields.vue'
import type {CdacSetting} from '../cdac'
import PayRuleFields from '../components/PayRuleFields.vue'
import PayItemFields from '../components/PayItemFields.vue'
import {WorkforceApiError} from '../api'
import type {ChangeWrite,ChangeProfileWrite} from '../payChanges'
import type {PayProfile} from '../payrollTypes'
import PayChangeHandoff from '../components/PayChangeHandoff.vue'
import AnnualWagePanel from '../components/AnnualWagePanel.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
import PayPlanEstimate from '../components/PayPlanEstimate.vue'
function profileStartDate(value:unknown){if(typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)){const date=new Date(value+'T00:00:00Z');if(!Number.isNaN(date.getTime())&&date.toISOString().slice(0,10)===value)return value}return storeToday()}
const step=ref(1),x=(z:string,e:string)=>english()?e:z
const handoff=ref<ChangeWrite|null>(null),profiles=ref<PayProfile[]>([])
const {pc}=usePayrollConfigurationText(),preview=ref<ProfilePreview|null>(null),previewBusy=ref(false)
let previewRevision=0
const route=useRoute(),router=useRouter(),editing=!!route.params.id,id=String(route.params.id||crypto.randomUUID()),{api,r,t,base,current,loading,busy,failure,notice,load,write,english}=usePayrollPage(),company=ref(''),found=ref(false),savedCdac=ref(false),savedTemplate=ref(''),employees=ref<Option[]>([]),employeeBirthDates=ref<Record<string,string>>({}),employeePrDocuments=ref<Record<string,PrDocument[]>>({}),prConfirmed=ref(false),templates=ref<SalaryTemplate[]>([]),draft=reactive({expectedVersion:0,employeeId:'',effectiveFrom:profileStartDate(route.query.effectiveFrom),templateId:'',rule:blankRule(),cpf:{citizenship:'',birthDate:'',prDate:null,prMode:'GG',electionReference:''} as Omit<CpfProfile,'citizenship'>&{citizenship:CpfProfile['citizenship']|''},payment:{method:'',bank:''} as {method:PaymentPreference['method']|'';bank:string},cdac:{status:'',reference:''} as {status:CdacSetting['status']|'';reference:string}})
const selectedBasis=ref<PayBasis|''>('')
watch(selectedBasis,basis=>{if(basis&&basis!==draft.rule.basis){draft.rule.basis=basis;changeBasis()}},{flush:'sync'})
const employeeBirthDate=computed(()=>employeeBirthDates.value[draft.employeeId]||'')
watch(()=>draft.employeeId,()=>{draft.cpf.birthDate=employeeBirthDate.value||'';if(found.value)clearPrReference()},{flush:'sync'})
watch(()=>draft.cpf.citizenship,()=>{if(found.value)clearPrReference()},{flush:'sync'})
const prDocuments=computed(()=>employeePrDocuments.value[draft.employeeId]||[]),selectedPrDocument=computed(()=>prDocuments.value.find(document=>document.id===draft.cpf.prDocumentId))
watch(()=>draft.cpf.prDocumentId,()=>{prConfirmed.value=false},{flush:'sync'})
function clearPrReference(){draft.cpf.prDate=null;draft.cpf.prDocumentId=null;prConfirmed.value=false}
function changePrSource(){prConfirmed.value=false;draft.cpf.prDate=selectedPrDocument.value?.prEffectiveOn||null}
function confirmPrSource(){if(prConfirmed.value&&selectedPrDocument.value)draft.cpf.prDate=selectedPrDocument.value.prEffectiveOn}
watch(()=>draft.cpf,()=>{if(employeeBirthDate.value)draft.cpf.birthDate=employeeBirthDate.value},{flush:'sync'})
async function apply(useDefault=false){const revision=++previewRevision;preview.value=null;if(!selectedBasis.value||!draft.employeeId||!company.value||!draft.effectiveFrom||(!useDefault&&!draft.templateId))return;previewBusy.value=true;const employee=draft.employeeId,date=draft.effectiveFrom,basis=draft.rule.basis;try{const p=await api().get<ProfilePreview>(`/pay-profile-preview?companyId=${company.value}&employeeId=${employee}&on=${date}&basis=${draft.rule.basis}`+(useDefault?'':'&templateId='+draft.templateId));if(current()&&revision===previewRevision&&draft.employeeId===employee&&draft.effectiveFrom===date&&draft.rule.basis===basis){preview.value=p;if(p.template){draft.templateId=p.template.id;draft.rule=copy(p.template.rule)}}}catch{if(current()&&revision===previewRevision)failure.value=pc('refresh')}finally{if(current()&&revision===previewRevision)previewBusy.value=false}}
watch(()=>[draft.employeeId,draft.effectiveFrom],()=>{previewRevision++;preview.value=null;previewBusy.value=false},{flush:'sync'})
function changeBasis(){changeTemplate();draft.templateId=''}
function changeTemplate(){previewRevision++;preview.value=null;previewBusy.value=false}
onMounted(()=>void load(async()=>{const h=await api().get<PayrollHomeData>('/payroll-home'),c=chooseCompany(h,String(route.query.companyId||''));if(route.query.companyId&&!h.companies.some(x=>x.id===route.query.companyId))throw new Error(pc('restricted'));const [data,ts]=await Promise.all([api().get<PayProfilePage>('/pay-profiles?companyId='+c),api().get<SalaryTemplate[]>('/salary-templates?companyId='+c)]);return {c,data,ts}},v=>{company.value=v.c;profiles.value=v.data.items;employees.value=v.data.employees;employeeBirthDates.value=v.data.employeeBirthDates||{};employeePrDocuments.value=v.data.employeePrDocuments||{};templates.value=v.ts;if(editing){const p=v.data.items.find(x=>x.id===id);if(!p){failure.value=t('notFound');return}savedCdac.value=!!p.cdac;savedTemplate.value=p.templateId;Object.assign(draft,{expectedVersion:p.version,employeeId:p.employeeId,effectiveFrom:p.effectiveFrom,templateId:p.templateId,rule:copy(p.rule),payment:p.payment?copy(p.payment):{method:'',bank:''},cdac:p.cdac?copy(p.cdac):{status:'',reference:''},cpf:{...copy(p.cpf),prDocumentId:p.cpf.prDocumentId||null}});selectedBasis.value=p.rule.basis}else{draft.employeeId=profileEmployee(employees.value,String(route.query.employeeId||''));draft.templateId=''}found.value=true;if(editing&&route.query.estimate==='1')step.value=3}))
function nextStep(){failure.value='';if(step.value===1){if(!draft.employeeId){failure.value=pc('choose');return}if(!selectedBasis.value){failure.value=x('请选择计薪方式','Choose a pay basis');return}if(!draft.templateId||!validRule(draft.rule)){failure.value=r('invalid');return}if((!editing||draft.templateId!==savedTemplate.value)&&!preview.value?.template){failure.value=pc('preview');return}}if(step.value===2){if(!['citizen','spr','foreign'].includes(draft.cpf.citizenship)||draft.cpf.citizenship!=='foreign'&&!draft.cpf.birthDate){failure.value=r('invalid');return}if(!editing&&!draft.cdac.status){failure.value=r('cdacDeclarationRequired');return}}step.value=Math.min(3,step.value+1)}
function invalidField(event:Event){const el=event.target as HTMLElement;const group=el.closest<HTMLElement>('[data-pay-step]');if(group)step.value=Number(group.dataset.payStep);el.closest('details')?.setAttribute('open','');queueMicrotask(()=>el.focus())}
function save(){if(!selectedBasis.value){step.value=1;failure.value=x('请选择计薪方式','Choose a pay basis');return}const c=draft.cpf;if(!['citizen','spr','foreign'].includes(c.citizenship)){step.value=2;failure.value=r('invalid');return}if(!company.value||!found.value)return;if(c.citizenship==='spr'&&c.prDocumentId&&(!selectedPrDocument.value||!prConfirmed.value||c.prDate!==selectedPrDocument.value.prEffectiveOn)){failure.value=r(!selectedPrDocument.value?'prDocumentReview':'prDocumentRequired');return}if((!editing||preview.value||draft.templateId!==savedTemplate.value)&&!preview.value?.template){failure.value=pc('preview');return}if(!draft.employeeId||!draft.templateId||!draft.effectiveFrom||!validRule(draft.rule)||(draft.cdac.status==='applicable'&&c.citizenship==='foreign')||(['exempt','manual'].includes(draft.cdac.status)&&!draft.cdac.reference.trim())||(draft.cdac.status&&draft.cdac.status!=='manual'&&draft.rule.items.some(i=>i.kind==='cdac'))||(draft.payment.method==='bank'&&!draft.payment.bank.trim())||(c.citizenship!=='foreign'&&!c.birthDate)||(c.citizenship==='spr'&&(!c.prDate||c.prMode!=='GG'&&!c.electionReference.trim()))){failure.value=r('invalid');return}const cpf:CpfProfile={citizenship:c.citizenship as CpfProfile['citizenship'],birthDate:c.birthDate||null,prDate:c.citizenship==='spr'?c.prDate:null,prMode:c.citizenship==='spr'?c.prMode:'GG',electionReference:c.citizenship==='spr'?c.electionReference.trim():'',prDocumentId:c.citizenship==='spr'?c.prDocumentId||null:null};const body={...draft,...(preview.value?.template?{expectedTemplateVersion:preview.value.template.version,defaultMappingId:preview.value.defaultMapping?.id||null,expectedDefaultVersion:preview.value.defaultMapping?.version??null,defaultBasis:preview.value.defaultMapping?draft.rule.basis:null}:{}),companyId:company.value,cpf,cdac:draft.cdac.status?{status:draft.cdac.status,reference:draft.cdac.reference.trim()}:null,payment:draft.payment.method?{method:draft.payment.method,bank:draft.payment.method==='cash'?'':draft.payment.bank.trim()}:null};void write(()=>api().put('/pay-profiles/'+id,body),async()=>{if(current())await router.push(payrollReturn.value||{path:base.value+'/pay-profiles',query:{companyId:company.value}})},e=>{if(!(e instanceof WorkforceApiError&&e.status===409&&e.code==='WORKFORCE_PAYROLL_APPROVAL_REQUIRED'))return false;handoff.value={expectedRevision:0,companyId:company.value,employeeId:draft.employeeId,effectiveDate:draft.effectiveFrom,adoptionId:null,profile:{expectedVersion:body.expectedVersion,companyId:body.companyId,employeeId:body.employeeId,effectiveFrom:body.effectiveFrom,templateId:body.templateId,expectedTemplateVersion:preview.value?.template?.version||templates.value.find(t=>t.id===draft.templateId)?.version||0,rule:copy(body.rule),cpf:copy(body.cpf),payment:copy(body.payment),cdac:copy(body.cdac)} as ChangeProfileWrite,derivedRule:null,months:[],reason:''};return true})}
</script>
<template><section class="wf-panel"><h2>{{r(editing?'editProfile':'newProfile')}}</h2><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><details v-if="company&&draft.employeeId" class="wf-task-section"><summary>{{x('年度工资与期初资料（按需核对）','Annual wages and opening facts (when needed)')}}</summary><AnnualWagePanel v-if="company&&draft.employeeId" :company-id="company" :employee-id="draft.employeeId" :year="Number(draft.effectiveFrom.slice(0,4))"/></details><PayChangeHandoff v-if="handoff" :seed="handoff" :employees="employees" :profiles="profiles" :templates="templates" :birth-dates="employeeBirthDates" :pr-documents="employeePrDocuments" @cancel="handoff=null"/><form v-else-if="found&&!loading" @submit.prevent="step===3?save():nextStep()" @invalid.capture="invalidField"><nav class="wf-subnav" :aria-label="x('薪资配置进度','Pay setup progress')"><span :aria-current="step===1?'step':undefined">1 {{x('确定待遇','Pay terms')}}</span><span :aria-current="step===2?'step':undefined">2 {{x('必要资料','Required facts')}}</span><span :aria-current="step===3?'step':undefined">3 {{x('核对并办理','Review and proceed')}}</span></nav><fieldset :disabled="busy"><section v-show="step===1" data-pay-step="1"><h3>{{x('1. 选员工与生效日，再带入岗位待遇','1. Choose employee and date, then apply terms')}}</h3><p class="wf-hint">{{x('先选择月薪、时薪或日薪，再预览并应用对应岗位默认；没有默认时再选择同计薪方式的模板。个人差异仅在本方案中调整。','Choose monthly, hourly or daily pay, then preview and apply the matching position default or template. Record personal differences in this plan.')}}</p><div class="wf-grid"><label>{{r('employee')}}<select v-model="draft.employeeId" :aria-label="r('employee')" required :disabled="editing"><option value="">{{pc('choose')}}</option><option v-for="e in employees" :key="e.id" :value="e.id">{{e.name}}</option></select></label><label>{{r('effectiveFrom')}}<input v-model="draft.effectiveFrom" required type="date" :disabled="editing"></label></div><label>{{r('basis')}}<select v-model="selectedBasis" required :aria-label="r('basis')"><option value="" disabled>{{x('请选择计薪方式','Choose a pay basis')}}</option><option value="monthly">{{r('monthly')}}</option><option value="hourly">{{r('hourly')}}</option><option value="daily">{{r('daily')}}</option></select></label><label>{{r('template')}}<select v-model="draft.templateId" required @change="changeTemplate"><option value="">—</option><option v-for="s in templates.filter(t=>t.rule.basis===selectedBasis)" :key="s.id" :value="s.id" :disabled="!s.enabled&&s.id!==draft.templateId">{{s.name}}</option></select></label><button type="button" :disabled="busy||previewBusy||!selectedBasis||!draft.employeeId" @click="apply(true)">{{pc('useDefault')}}</button><button type="button" :disabled="busy||previewBusy||!selectedBasis||!draft.employeeId||!draft.templateId" @click="apply()">{{pc('preview')}}</button><p class="wf-hint">{{preview?.template?pc('applied'):preview?pc('none'):r('templateHint')}}</p><label>{{r('rate')}}<input v-model="draft.rule.rate" required inputmode="decimal"></label><p class="wf-hint">{{x('标准待遇已带入；仅本人议定工资不同时修改。','Standard terms are filled in. Change the rate only for a personal agreement.')}}</p><h3>{{x('月津贴与全勤奖','Monthly allowances and attendance bonus')}}</h3><PayItemFields :items="draft.rule.items" recurring :disabled="busy"/><details><summary>{{x('查看标准明细 / 维护个人差异','Standard details / personal differences')}}</summary><PayRuleFields :rule="draft.rule" :disabled="busy" basis-locked hide-items hide-pay-terms/></details></section><section v-show="step===2" data-pay-step="2"><p class="wf-hint">{{x('先确认付款偏好、员工身份与出生日期，再核对PR及CDAC资料。系统复用现有法定规则，请勿手工重复加入CPF或SDL项目。','Confirm payment preference, identity and date of birth, then PR and CDAC facts. Existing statutory rules apply; do not duplicate CPF or SDL as manual items.')}}</p><h2 class="wf-section">{{r('paymentPlan')}}</h2><div class="wf-grid"><label>{{r('method')}}<select v-model="draft.payment.method"><option value="">{{r('paymentUnknown')}}</option><option value="cash">{{r('cash')}}</option><option value="bank">{{r('bank')}}</option><option value="paynow">{{r('paynow')}}</option><option value="other">{{r('other')}}</option></select></label><label v-if="draft.payment.method&&draft.payment.method!=='cash'">{{r('bankName')}}<input v-model="draft.payment.bank" maxlength="100" :required="draft.payment.method==='bank'"></label></div><h2 class="wf-section">{{r('contributions')}}</h2><label>{{r('citizenship')}}<select v-model="draft.cpf.citizenship" :aria-label="r('citizenship')"><option value="" disabled>{{x('请选择身份','Choose citizenship status')}}</option><option value="citizen">{{r('citizen')}}</option><option value="spr">{{r('spr')}}</option><option value="foreign">{{r('foreign')}}</option></select></label><label>{{r('birthDate')}}<input v-model="draft.cpf.birthDate" type="date" :readonly="!!employeeBirthDate" :required="draft.cpf.citizenship!=='foreign'"></label><p v-if="employeeBirthDate" class="wf-hint">{{r('birthDateSource')}}</p><template v-if="draft.cpf.citizenship==='spr'"><label>{{r('prDateSource')}}<select v-model="draft.cpf.prDocumentId" :aria-label="r('prDateSource')" @change="changePrSource"><option :value="null">{{r('prManual')}}</option><option v-if="draft.cpf.prDocumentId&&!selectedPrDocument" :value="draft.cpf.prDocumentId" disabled>{{r('prDocumentMissing')}}</option><option v-for="document in prDocuments" :key="document.id" :value="document.id">{{document.typeName}} · {{document.number||document.holderName||document.id}} · {{document.prEffectiveOn}}</option></select></label><p class="wf-hint">{{r('prDocumentHint')}}</p><p v-if="draft.cpf.prDocumentId&&(!selectedPrDocument||draft.cpf.prDate!==selectedPrDocument.prEffectiveOn)" role="alert">{{r('prDocumentReview')}}</p><p v-if="selectedPrDocument" class="wf-hint">{{selectedPrDocument.holderName}} · {{r('prDocumentApproval')}}: {{selectedPrDocument.approvedOn||'—'}} · {{r('prDocumentDate')}}: {{selectedPrDocument.prEffectiveOn}}</p><label>{{r('prDate')}}<input v-model="draft.cpf.prDate" :aria-label="r('prDate')" :readonly="!!draft.cpf.prDocumentId" required type="date"></label><label v-if="selectedPrDocument" class="wf-inline"><input v-model="prConfirmed" :aria-label="r('prDocumentConfirm')" type="checkbox" @change="confirmPrSource">{{r('prDocumentConfirm')}}</label><label>{{r('prMode')}}<select v-model="draft.cpf.prMode"><option value="GG">{{r('GG')}}</option><option value="FG">{{r('FG')}}</option><option value="FF">{{r('FF')}}</option></select></label><label v-if="draft.cpf.prMode!=='GG'">{{r('electionReference')}}<textarea v-model="draft.cpf.electionReference" required maxlength="500" rows="2"></textarea></label></template><CdacProfileFields :configured="savedCdac" :setting="draft.cdac" :items="draft.rule.items" :citizenship="draft.cpf.citizenship"/></section><section v-show="step===3" data-pay-step="3"><h3>{{x('核对薪资方案','Review pay plan')}}</h3><dl class="wf-details"><dt>{{r('employee')}}</dt><dd>{{employees.find(e=>e.id===draft.employeeId)?.name}}</dd><dt>{{r('effectiveFrom')}}</dt><dd>{{draft.effectiveFrom}}</dd><dt>{{r('template')}}</dt><dd>{{templates.find(t=>t.id===draft.templateId)?.name}}</dd><dt>{{r('basis')}}</dt><dd>{{r(draft.rule.basis)}} · SGD {{draft.rule.rate}}</dd><dt>{{r('citizenship')}}</dt><dd>{{draft.cpf.citizenship?r(draft.cpf.citizenship):'—'}}</dd></dl><PayPlanEstimate @edit-facts="step=2" :company-id="company" :employee-id="draft.employeeId"  :initial-month="String(route.query.month||'')" :effective-from="draft.effectiveFrom" :rule="draft.rule" :cpf="draft.cpf" :cdac="draft.cdac"/><p class="wf-hint">{{x('保存待遇方案不等于确认工资或付款；需要审批时将继续办理申请。','Saving terms does not confirm payroll or make a payment. Required approvals continue as a request.')}}</p></section></fieldset><p class="wf-hint">{{r('profileHint')}} {{r('supportHint')}}</p><footer class="wf-form-actions"><RouterLink class="wf-button" :to="payrollReturn||{path:base+'/pay-profiles',query:{companyId:company}}">{{t('cancel')}}</RouterLink><button v-if="step>1" type="button" :disabled="busy" @click="step--">{{x('上一步','Back')}}</button><button v-if="step<3" type="button" class="primary" :disabled="busy||previewBusy" @click="nextStep">{{step===1?x('下一步：必要资料','Next: required facts'):x('下一步：核对方案','Next: review')}}</button><button v-else class="primary" :disabled="busy||previewBusy">{{busy?t('saving'):t('save')}}</button></footer></form></section></template>
